    }
    if phase < 0.0 {
        phase += period;
    }
    let mut pat = 0usize;
    for _ in 0..=exp {
        if phase < dashes[pat % dashes.len()] {
            break;
        }
        w.step(1, control)?;
        phase -= dashes[pat % dashes.len()];
        pat = (pat + 1) % exp;
    }
    let mut remain = dashes[pat % dashes.len()] - phase;
    if !remain.is_finite() || remain <= 0.0 {
        return Err(dash_limit());
    }
    let mut joins_prev = false;
    for i in 0..n {
        w.step(1, control)?;
        let e = *edges
            .get(first.checked_add(i).ok_or_else(dash_limit)?)
            .ok_or_else(dash_limit)?;
        let dx = e.b.x - e.a.x;
        let dy = e.b.y - e.a.y;
        let len = dx.hypot(dy);
        if !len.is_finite() {
            return Err(dash_limit());
        }
        if len == 0.0 {
            continue;
        }
        let (mut at, mut cont) = (0.0, false);
        while at < len {
            w.step(1, control)?;
            let take = remain.min(len - at);
            let end = at + take;
            if take <= 0.0 || !end.is_finite() {
                return Err(dash_limit());
            }
            let on = pat % 2 == 0;
            let continues = on && end == len && remain - take > 1.0e-12;
            let cross = continues && i + 1 < n;
            if on {
                let a = Point {
                    x: e.a.x + dx * (at / len),
                    y: e.a.y + dy * (at / len),
                };
                let b = Point {
                    x: e.a.x + dx * (end / len),
                    y: e.a.y + dy * (end / len),
                };
                let sc = if at == 0.0 && (joins_prev || (seam && i == 0)) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                let ec = if cross || (end == len && seam && i + 1 == n) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                w.segment(Edge { a, b }, sc, ec, control)?;
            }
            if cross {
                cont = true;
            }
            at = end;
            remain -= take;
            if remain <= 1.0e-12 {
                pat = (pat + 1) % exp;
                remain = dashes[pat % dashes.len()];
            }
        }
        if cont && i + 1 < n {
            w.join(
                e,
                *edges.get(first + i + 1).ok_or_else(dash_limit)?,
                control,
            )?;
        }
        joins_prev = cont;
    }
    if seam {
        w.join(
            *edges.get(first + n - 1).ok_or_else(dash_limit)?,
            *edges.get(first).ok_or_else(dash_limit)?,
            control,
        )?;
    }
    Ok(())
}
fn solid(
    w: &mut Writer<'_>,
    stroke: &Stroke,
    edges: &[Edge],
    first: usize,
    count: usize,
    closed: bool,
    implicit: bool,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let mut n = count;
    if !closed && implicit && n > 0 {
        n -= 1;
    }
    if n == 0 {
        return Ok(());
    }
    for i in 0..n {
        w.step(1, control)?;
        let e = *edges
            .get(first.checked_add(i).ok_or_else(dash_limit)?)
            .ok_or_else(dash_limit)?;
        let cap = if !closed && (i == 0 || i + 1 == n) {
            stroke.cap
        } else {
            Linecap::Butt
        };
        w.segment(e, cap, cap, control)?;
    }
    let joins = if closed { n } else { n - 1 };
    for i in 0..joins {
        w.step(1, control)?;
        let next = if closed { (i + 1) % n } else { i + 1 };
        w.join(
            edges[first + (next + n - 1) % n],
            edges[first + next],
            control,
        )?;
    }
    Ok(())
}

/// Build dash records directly in the admitted same-job buffers. The returned
/// descriptor has no borrowed source or temporary cache storage.
pub fn build_dash_cache(
    view: SceneView<'_>,
    local_edges: &[Edge],
    seams: &[bool],
    job: &mut RasterJob,
    scratch: &mut JobRasterScratch,
    control: &mut dyn WorkControl,
) -> Result<JobDashCache> {
    if view.shapes.len() > 65_536 {
        return Err(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Shapes),
            offset: 0,
        });
    }
    job.validate_source(view.source_owner())?;
    // Build into new admitted buffers. The published cache remains intact until
    // dash records and every grid finish successfully; growth accounts for the
    // real old/new overlap through RasterJob's ChargeLedger admission.
    let segments = job.buffer(RasterPool::Dash, usize::MAX, control)?;
    let joins = match job.buffer(RasterPool::Dash, usize::MAX, control) {
        Ok(handle) => handle,
        Err(error) => {
            let _ = job.release(segments);
            return Err(error);
        }
    };
    let shapes = match job.buffer(RasterPool::Dash, 65_536, control) {
        Ok(handle) => handle,
        Err(error) => {
            let _ = job.release(segments);
            let _ = job.release(joins);
            return Err(error);
        }
    };
    let desc = JobDashCache {
        segments,
        joins,
        shapes,
        build_steps: 0,
    };
    let mut capacity = crate::cache_capacity::CacheCapacity::default();
    if let Err(error) = capacity.reserve(job, desc.shapes, view.shapes.len(), control) {
        let _ = release_cache(job, desc);
        return Err(error);
    }
    let empty_cells = if view.shapes.is_empty() {
        None
    } else {
        match job.buffer::<vexel_scene::GridCell>(RasterPool::Grid, 0, control) {
            Ok(handle) => Some(handle),
            Err(error) => {
                let _ = release_cache(job, desc);
                return Err(error);
            }
        }
    };
    let empty_refs = if view.shapes.is_empty() {
        None
    } else {
        match job.buffer::<u32>(RasterPool::Grid, 0, control) {
            Ok(handle) => Some(handle),
            Err(error) => {
                if let Some(cells) = empty_cells {
                    let _ = job.release(cells);
                }
                let _ = release_cache(job, desc);
                return Err(error);
            }
        }
    };
    let result = (|| {
        let mut w = Writer {
            job,
            cache: desc,
            steps: 0,
            capacity,
        };
        for (i, shape) in view.shapes.iter().enumerate() {
            w.step(1, control)?;
            let segment_first = w.job.slice(desc.segments)?.len();
            let join_first = w.job.slice(desc.joins)?.len();
            if shape.stroke.rgba[3] != 0 && shape.stroke.width > 0.0 {
                let dashes = shape
                    .stroke
                    .dash_values
                    .slice(view.dash_values)
                    .ok_or_else(dash_limit)?;
                let subpaths = shape
                    .subpaths
                    .slice(view.path_subpaths)
                    .ok_or_else(dash_limit)?;
                if !subpaths.is_empty() {
                    for (si, sub) in subpaths.iter().enumerate() {
                        let seam = seams
                            .get(view.shapes.len() + shape.subpaths.first + si)
                            .copied()
                            .unwrap_or(false);
                        if dashes.is_empty() {
                            solid(
                                &mut w,
                                &shape.stroke,
                                local_edges,
                                sub.first_edge,
                                sub.edge_count,
                                sub.closed,
                                true,
                                control,
                            )?;
                        } else {
                            dashed(
                                &mut w,
                                &shape.stroke,
                                dashes,
                                local_edges,
                                sub.first_edge,
                                sub.edge_count,
                                sub.closed,
                                true,
                                seam,
                                control,
                            )?;
                        }
                    }
                } else {
                    let seam = seams.get(i).copied().unwrap_or(false);
                    if dashes.is_empty() {
                        solid(
                            &mut w,
                            &shape.stroke,
                            local_edges,
                            shape.edges.first,
                            shape.edges.count,
                            shape.stroke_closed,
                            shape.filled,
                            control,
                        )?;
                    } else {
                        dashed(
                            &mut w,
                            &shape.stroke,
                            dashes,
                            local_edges,
                            shape.edges.first,
                            shape.edges.count,
                            shape.stroke_closed,
                            shape.filled,
                            seam,
                            control,
                        )?;
                    }
                }
            }
            let segment_end = w.job.slice(desc.segments)?.len();
            let join_end = w.job.slice(desc.joins)?.len();
            let range = JobDashRange {
                segments: range(segment_first, segment_end)?,
                joins: range(join_first, join_end)?,
                grid_cells: empty_cells.ok_or_else(dash_limit)?,
                grid_refs: empty_refs.ok_or_else(dash_limit)?,
                grid_min_x: 0.0,
                grid_min_y: 0.0,
                grid_cell_size: 0.0,
                grid_columns: 0,
                grid_rows: 0,
            };
            w.job.extend(desc.shapes, &[range], control)?;
        }
        let cache = JobDashCache {
            build_steps: w.steps,
            ..desc
        };
        crate::job_grid::build_stroke_grid(view, w.job, cache, &mut w.capacity, control)?;
        Ok(JobDashCache {
            build_steps: w.steps,
            ..desc
        })
    })();
    if let Err(error) = result {
        let _ = release_cache(job, desc);
        if let Some(handle) = empty_cells {
            let _ = job.release(handle);
        }
        if let Some(handle) = empty_refs {
            let _ = job.release(handle);
        }
        return Err(error);
    }
    let cache = result?;
    // Shared zero-capacity handles are not referenced once every shape has a
    // grid. Release them explicitly rather than losing their registry slots.
    if !job.slice(cache.shapes)?.iter().any(|r| r.grid_columns == 0) {
        if let Some(handle) = empty_cells {
            job.release(handle)?;
        }
        if let Some(handle) = empty_refs {
            job.release(handle)?;
        }
    }
    release_cache(job, scratch.dash)?;
    scratch.dash = cache;
    Ok(cache)
}

fn release_cache(job: &mut RasterJob, cache: JobDashCache) -> Result<()> {
    let mut empty = None;
    let count = job.slice(cache.shapes)?.len();
    for i in 0..count {
        let range = job.slice(cache.shapes)?[i];
        if range.grid_columns != 0 {
            job.release(range.grid_cells)?;
            job.release(range.grid_refs)?;
        } else if empty.is_none() {
            empty = Some((range.grid_cells, range.grid_refs));
        }
    }
    if let Some((cells, refs)) = empty {
        job.release(cells)?;
        job.release(refs)?;
    }
    job.release(cache.segments)?;
    job.release(cache.joins)?;
    job.release(cache.shapes)
}

pub(crate) fn tagged_index(reference: u32) -> (bool, usize) {
    (
        reference & STROKE_GRID_JOIN_BIT != 0,
        (reference & !STROKE_GRID_JOIN_BIT) as usize,
    )
}
use crate::{
    STROKE_GRID_JOIN_BIT, STROKE_GRID_MAX_AXIS, STROKE_GRID_MAX_CELLS, STROKE_GRID_MAX_REFS,
    stopped,
};
use vexel_geometry::Point;
use vexel_scene::{
    DashSegment, GridCell, JobDashCache, JobDashRange, RasterJob, RasterPool, Result, SceneView,
    WorkControl, WorkKind,
};

fn cap_error() -> vexel_scene::Diagnostic {
    vexel_scene::Diagnostic {
        kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::DashCache),
        offset: 0,
    }
}
fn capacity_fallback(error: vexel_scene::Diagnostic) -> bool {
    matches!(
        error.kind,
        vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::DashCache)
            | vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Grid)
    )
}
fn bounds_segment(s: &DashSegment, radius: f64) -> [f64; 4] {
    let margin = if s.start_cap == vexel_scene::Linecap::Square
        || s.end_cap == vexel_scene::Linecap::Square
    {
        radius * std::f64::consts::SQRT_2
    } else {
        radius
    };
    [
        s.edge.a.x.min(s.edge.b.x) - margin,
        s.edge.a.y.min(s.edge.b.y) - margin,
        s.edge.a.x.max(s.edge.b.x) + margin,
        s.edge.a.y.max(s.edge.b.y) + margin,
    ]
}
fn join_bounds(p: Point, radius: f64) -> [f64; 4] {
    [p.x - radius, p.y - radius, p.x + radius, p.y + radius]
}
fn axis(x: f64, range: &JobDashRange, horizontal: bool) -> Option<usize> {
    let (origin, size, count) = if horizontal {
        (range.grid_min_x, range.grid_cell_size, range.grid_columns)
    } else {
        (range.grid_min_y, range.grid_cell_size, range.grid_rows)
    };
    let mut value = (x - origin) / size;
    if !value.is_finite() || value < -1.0 || count == 0 {
        return None;
    }
    if value < 0.0 {
        value = 0.0;
    }
    let cell = value.floor().min(count as f64 - 1.0);
    (cell >= 0.0).then_some(cell as usize)
}
fn bbox(b: [f64; 4], r: &JobDashRange) -> Option<(usize, usize, usize, usize)> {
    Some((
        axis(b[0], r, true)?,
        axis(b[1], r, false)?,
        axis(b[2], r, true)?,
        axis(b[3], r, false)?,
    ))
}
/// Build every shape grid in admitted same-job buffers. Oversized cell/ref/byte
/// grids follow the frozen scalar fallback; cancellation and admission errors
/// propagate without publishing a partially filled range.
pub(crate) fn build_stroke_grid(
    view: SceneView<'_>,
    job: &mut RasterJob,
    cache: JobDashCache,
    capacity: &mut crate::cache_capacity::CacheCapacity,
    control: &mut dyn WorkControl,
) -> Result<()> {
    if job.slice(cache.shapes)?.len() != view.shapes.len() {
        return Err(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::InvalidArgument,
            offset: 0,
        });
    }
    let mut total_cells = 0usize;
    let mut total_refs = 0usize;
    for i in 0..view.shapes.len() {
        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
        let mut range = *job.slice(cache.shapes)?.get(i).ok_or_else(cap_error)?;
        range.grid_min_x = 0.0;
        range.grid_min_y = 0.0;
        range.grid_cell_size = 0.0;
        range.grid_columns = 0;
        range.grid_rows = 0;
        let primitive = range
            .segments
            .count
            .checked_add(range.joins.count)
            .ok_or_else(cap_error)?;
        if primitive == 0 {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let shape = &view.shapes[i];
        let radius = shape.stroke.width * 0.5;
        let mut minx = f64::INFINITY;
        let mut miny = f64::INFINITY;
        let mut maxx = f64::NEG_INFINITY;
        let mut maxy = f64::NEG_INFINITY;
        let sr = range.segments.first..range.segments.end().ok_or_else(cap_error)?;
        let jr = range.joins.first..range.joins.end().ok_or_else(cap_error)?;
        if sr.end > job.slice(cache.segments)?.len() || jr.end > job.slice(cache.joins)?.len() {
            return Err(vexel_scene::Diagnostic {
                kind: vexel_scene::ErrorKind::InvalidArgument,
                offset: 0,
            });
        }
        for index in sr.clone() {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            let seg = job.slice(cache.segments)?[index];
            let b = bounds_segment(&seg, radius);
            minx = minx.min(b[0]);
            miny = miny.min(b[1]);
            maxx = maxx.max(b[2]);
            maxy = maxy.max(b[3]);
        }
        let jradii = if shape.stroke.join == vexel_scene::Linejoin::Miter {
            radius * shape.stroke.miter_limit
        } else {
            radius
        };
        for index in jr.clone() {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            let j = job.slice(cache.joins)?[index];
            let b = join_bounds(j.vertex, jradii);
            minx = minx.min(b[0]);
            miny = miny.min(b[1]);
            maxx = maxx.max(b[2]);
            maxy = maxy.max(b[3]);
        }
        let sx = maxx - minx;
        let sy = maxy - miny;
        if !sx.is_finite() || !sy.is_finite() {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let size = 1.0f64.max(sx.max(sy) / STROKE_GRID_MAX_AXIS as f64);
        let cols = (sx / size).ceil().max(1.0);
        let rows = (sy / size).ceil().max(1.0);
        if cols > 128.0 || rows > 128.0 {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        range.grid_min_x = minx;
        range.grid_min_y = miny;
        range.grid_cell_size = size;
        range.grid_columns = cols as u16;
        range.grid_rows = rows as u16;
        let cell_count = (cols as usize)
            .checked_mul(rows as usize)
            .ok_or_else(cap_error)?;
        if total_cells
            .checked_add(cell_count)
            .is_none_or(|n| n > STROKE_GRID_MAX_CELLS)
        {
            range.grid_columns = 0;
            range.grid_rows = 0;
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        // Original byte refusal precedes allocation (including handle metadata).
        if !capacity.admits::<GridCell>(cell_count) {
            range.grid_columns = 0;
            range.grid_rows = 0;
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let cells_handle =
            job.buffer::<GridCell>(RasterPool::Grid, STROKE_GRID_MAX_CELLS, control)?;
        let mut refs_handle = None;
        let mut staged_capacity = *capacity;
        let built = (|| -> Result<Option<(vexel_scene::JobBuffer<u32>, usize)>> {
            if let Err(error) = staged_capacity.reserve(job, cells_handle, cell_count, control) {
                if capacity_fallback(error) {
                    return Ok(None);
                }
                return Err(error);
            }
            let zero = GridCell { first: 0, count: 0 };
            for _ in 0..cell_count {
                job.extend(cells_handle, &[zero], control)?;
            }
            let mut count = 0usize;
            let mut fits = true;
            for p in 0..primitive {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let b = if p < range.segments.count {
                    let seg = job.slice(cache.segments)?[range.segments.first + p];
                    bounds_segment(&seg, radius)
                } else {
                    let join =
                        job.slice(cache.joins)?[range.joins.first + p - range.segments.count];
                    join_bounds(join.vertex, jradii)
                };
                if p < range.segments.count
                    && ![b[0], b[1], b[2], b[3]].into_iter().all(f64::is_finite)
                {
                    fits = false;
                    break;
                }
                let Some((x0, y0, x1, y1)) = bbox(b, &range) else {
                    fits = false;
                    break;
                };
                for cy in y0..=y1 {
                    for cx in x0..=x1 {
                        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                        let index = cy * cols as usize + cx;
                        let next = job.slice(cells_handle)?[index]
                            .count
                            .checked_add(1)
                            .ok_or_else(cap_error)?;
                        job.slice_mut(cells_handle)?[index].count = next;
                        count = count.checked_add(1).ok_or_else(cap_error)?;
                    }
                }
            }
            if !fits
                || total_refs
                    .checked_add(count)
                    .is_none_or(|n| n > STROKE_GRID_MAX_REFS)
            {
                return Ok(None);
            }
            if !staged_capacity.admits::<u32>(count) {
                return Ok(None);
            }
            let refs = job.buffer::<u32>(RasterPool::Grid, STROKE_GRID_MAX_REFS, control)?;
            refs_handle = Some(refs);
            if let Err(error) = staged_capacity.reserve(job, refs, count, control) {
                if capacity_fallback(error) {
                    return Ok(None);
                }
                return Err(error);
            }
            for _ in 0..count {
                job.extend(refs, &[0u32], control)?;
            }
            let mut offset = 0usize;
            for cell in job.slice_mut(cells_handle)? {
                let n = cell.count;
                cell.first = offset;
                cell.count = 0;
                offset = offset.checked_add(n).ok_or_else(cap_error)?;
            }
            for p in 0..primitive {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let b = if p < range.segments.count {
                    let seg = job.slice(cache.segments)?[range.segments.first + p];
                    bounds_segment(&seg, radius)
                } else {
                    let join =
                        job.slice(cache.joins)?[range.joins.first + p - range.segments.count];
                    join_bounds(join.vertex, jradii)
                };
                let (x0, y0, x1, y1) = bbox(b, &range).ok_or_else(cap_error)?;
                let encoded = if p < range.segments.count {
                    let index = range.segments.first + p;
                    if index >= STROKE_GRID_JOIN_BIT as usize {
                        return Err(cap_error());
                    }
                    u32::try_from(index).map_err(|_| cap_error())?
                } else {
                    let index = range.joins.first + p - range.segments.count;
                    if index >= STROKE_GRID_JOIN_BIT as usize {
                        return Err(cap_error());
                    }
                    STROKE_GRID_JOIN_BIT | index as u32
                };
                for cy in y0..=y1 {
                    for cx in x0..=x1 {
                        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                        let cell_index = cy * cols as usize + cx;
                        let cell = job.slice(cells_handle)?[cell_index];
                        let ref_index = cell.first.checked_add(cell.count).ok_or_else(cap_error)?;
                        job.slice_mut(refs)?[ref_index] = encoded;
                        job.slice_mut(cells_handle)?[cell_index].count += 1;
                    }
                }
            }
            Ok(Some((refs, count)))
        })();
        match built {
            Ok(Some((refs, count))) => {
                *capacity = staged_capacity;
                range.grid_cells = cells_handle;
                range.grid_refs = refs;
                total_cells += cell_count;
                total_refs += count;
                job.slice_mut(cache.shapes)?[i] = range;
            }
            Ok(None) => {
                if let Some(refs) = refs_handle {
                    job.release(refs)?;
                }
                job.release(cells_handle)?;
                range.grid_columns = 0;
                range.grid_rows = 0;
                job.slice_mut(cache.shapes)?[i] = range;
            }
            Err(error) => {
                if let Some(refs) = refs_handle {
                    let _ = job.release(refs);
                }
                let _ = job.release(cells_handle);
                return Err(error);
            }
        }
    }
    Ok(())
}

//! Logical generations share one physical ledger. No heap transaction registry.
use crate::{
    types::{invalid, stopped},
    *,
};

/// Same-job publication token. Copies become stale together when replaced.
#[derive(Debug, Clone, Copy)]
pub struct CacheGeneration {
    cache: JobDashCache,
    scope: u64,
}
/// Exclusive construction borrow; dropping or aborting retires only staged data.
/// No job/Vec/lease escape. Handles remain bound to their original generation.
pub struct CacheTransaction<'a> {
    job: &'a mut RasterJob,
    scope: u64,
    old: Option<CacheGeneration>,
    committed: bool,
}
impl RasterJob {
    pub(crate) fn cache_scope(&self, cache: JobDashCache, staged: bool) -> Result<u64> {
        self.require_pool(cache.segments, RasterPool::Dash)?;
        self.require_pool(cache.joins, RasterPool::Dash)?;
        self.require_pool(cache.shapes, RasterPool::Dash)?;
        let scope = self.checked(cache.segments)?.scope;
        for s in [
            self.checked(cache.segments)?,
            self.checked(cache.joins)?,
            self.checked(cache.shapes)?,
        ] {
            if s.scope != scope || (!staged && !s.published) {
                return Err(invalid(0));
            }
        }
        Ok(scope)
    }
    fn generation(&self, generation: CacheGeneration) -> Result<()> {
        if generation.scope == 0 || self.cache_scope(generation.cache, false)? != generation.scope {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Starts an explicit per-cache 16MiB/65536-cell/1M-reference generation.
    /// Physical old/new overlap, registry growth and history use the caller ledger.
    pub fn begin_cache<'a>(
        &'a mut self,
        source: &SourceOwner,
        old: Option<CacheGeneration>,
        control: &mut dyn WorkControl,
    ) -> Result<CacheTransaction<'a>> {
        self.validate_source(source)?;
        if self.cache_transaction.is_some() {
            return Err(invalid(0));
        }
        if let Some(old) = old {
            self.cache_view(old, control)?;
        }
        control.checkpoint().map_err(stopped)?;
        let scope = self.next;
        self.next = scope.checked_add(1).ok_or_else(crate::memory::arithmetic)?;
        self.cache_transaction = Some(scope);
        Ok(CacheTransaction {
            job: self,
            scope,
            old,
            committed: false,
        })
    }
    /// Descriptor compatibility for existing lower readers/composition. Each use
    /// still validates liveness, roles and generation; this transfers no ownership.
    pub fn cache_descriptor(&self, generation: CacheGeneration) -> Result<JobDashCache> {
        self.generation(generation)?;
        Ok(generation.cache)
    }
    pub fn cache_view(
        &self,
        generation: CacheGeneration,
        control: &mut dyn WorkControl,
    ) -> Result<JobDashView<'_>> {
        self.dash_view(self.cache_descriptor(generation)?, control)
    }
    pub(crate) fn release_scope(&mut self, scope: u64) -> Result<()> {
        for i in 0..self.slots.len() {
            if self.slots[i].active && self.slots[i].scope == scope {
                self.release_slot(i)?;
            }
        }
        Ok(())
    }
}
impl CacheTransaction<'_> {
    fn require<T: JobElement>(&self, h: JobBuffer<T>) -> Result<()> {
        if self.job.checked(h)?.scope != self.scope {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Uses the actual typed job arena; only original Dash/Grid roles are legal.
    pub fn buffer<T: JobElement>(
        &mut self,
        pool: RasterPool,
        cap: usize,
        control: &mut dyn WorkControl,
    ) -> Result<JobBuffer<T>> {
        if !matches!(pool, RasterPool::Dash | RasterPool::Grid) {
            return Err(invalid(0));
        }
        self.job.scoped_buffer(pool, cap, self.scope, control)
    }
    pub fn reserve<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.reserve(h, capacity, control)
    }
    pub fn extend<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        values: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.extend(h, values, control)
    }
    pub fn slice<T: JobElement>(&self, h: JobBuffer<T>) -> Result<&[T]> {
        self.require(h)?;
        self.job.slice(h)
    }
    pub fn slice_mut<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<&mut [T]> {
        self.require(h)?;
        self.job.slice_mut(h)
    }
    pub fn capacity<T: JobElement>(&self, h: JobBuffer<T>) -> Result<usize> {
        self.require(h)?;
        self.job.capacity(h)
    }
    pub fn truncate<T: JobElement>(&mut self, h: JobBuffer<T>, len: usize) -> Result<()> {
        self.require(h)?;
        self.job.truncate(h, len)
    }
    pub fn shrink_to<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.shrink_to(h, capacity, control)
    }
    pub fn clear_capacity<T: JobElement>(
        &mut self,
        h: JobBuffer<T>,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(h)?;
        self.job.clear_capacity(h, control)
    }
    pub fn release<T: JobElement>(&mut self, h: JobBuffer<T>) -> Result<()> {
        self.require(h)?;
        self.job.release(h)
    }
    pub fn stats(&self) -> RenderMemoryStats {
        self.job.stats()
    }
    /// Validate actual payload and same-scope grids before retiring any old slot.
    /// Consuming self makes duplicate commit impossible; copied descriptors confer
    /// no publication authority. Validation failure invokes unconditional cleanup.
    /// ```compile_fail,E0382
    /// use vexel_scene::*;
    /// fn replay(tx: CacheTransaction<'_>, cache: JobDashCache, c: &mut dyn WorkControl) {
    ///     let _ = tx.commit(cache, c);
    ///     let _ = tx.commit(cache, c); // publication authority was consumed
    /// }
    /// ```
    pub fn commit(
        mut self,
        cache: JobDashCache,
        control: &mut dyn WorkControl,
    ) -> Result<CacheGeneration> {
        if self.job.cache_scope(cache, true)? != self.scope {
            return Err(invalid(0));
        }
        self.job.dash_view_staged(cache, control)?;
        if let Some(old) = self.old {
            self.job.generation(old)?;
        }
        control.checkpoint().map_err(stopped)?;
        // No allocation/cancellation/fallible validation after this boundary.
        if let Some(old) = self.old {
            self.job.release_scope(old.scope)?;
        }
        for s in &mut self.job.slots {
            if s.active && s.scope == self.scope {
                s.published = true;
            }
        }
        self.job.cache_transaction = None;
        self.committed = true;
        Ok(CacheGeneration {
            cache,
            scope: self.scope,
        })
    }
    pub fn abort(self) {
        drop(self);
    }
}
impl Drop for CacheTransaction<'_> {
    fn drop(&mut self) {
        if !self.committed {
            // Private leases cannot be corrupted by callers. If cleanup ever
            // fails, unpublished slots remain and finish refuses success.
            if self.job.release_scope(self.scope).is_ok() {
                self.job.cache_transaction = None;
            }
        }
    }
}
//! Logical retained cache payload, separate from the job ledger's physical
//! old/new overlap and metadata history. One instance per staged cache.
use crate::DASH_CACHE_BYTE_LIMIT;
use vexel_scene::{
    Diagnostic, ErrorKind, JobBuffer, JobElement, LimitKind, RasterJob, Result, WorkControl,
};

pub(crate) fn limit() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::DashCache),
        offset: 0,
    }
}

#[derive(Clone, Copy, Default)]
pub(crate) struct CacheCapacity {
    used: usize,
}
impl CacheCapacity {
    fn replacing<T>(&self, old: usize, new: usize) -> Result<usize> {
        let size = std::mem::size_of::<T>();
        self.used
            .checked_sub(old.checked_mul(size).ok_or_else(limit)?)
            .and_then(|n| n.checked_add(new.checked_mul(size)?))
            .filter(|&n| n <= DASH_CACHE_BYTE_LIMIT)
            .ok_or_else(limit)
    }
    pub(crate) fn admits<T>(&self, count: usize) -> bool {
        self.replacing::<T>(0, count).is_ok()
    }
    pub(crate) fn reserve<T: JobElement>(
        &mut self,
        job: &mut RasterJob,
        handle: JobBuffer<T>,
        requested: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let old = job.capacity(handle)?;
        if requested <= old {
            return Ok(());
        }
        // Predict before allocation; then verify the allocator's actual capacity.
        self.replacing::<T>(old, requested)?;
        job.reserve(handle, requested, control)?;
        self.used = self.replacing::<T>(old, job.capacity(handle)?)?;
        Ok(())
    }
}
