        assert!(2 * n - 1 < 1_000_000);
        assert!(cache.build_steps < 1_000_000);
        assert_eq!(
            retained(&job, cache),
            if extra == 1 {
                CAP - 12
            } else {
                176_371 * (size_of::<DashSegment>() + size_of::<DashJoin>())
                    + 2 * size_of::<JobDashRange>()
                    + size_of::<GridCell>()
                    + 4
            }
        );
        job.dash_view(cache, &mut Run).unwrap();
    }
}
